$error=null;$runtime=[];$sessions=[];try{$pdo=business_db();deployment_step19_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=deployment_step19_context($pdo);$orgId=(int)$ctx['organization_id'];$runtime=deployment_step19_runtime_checks($pdo);$s=$pdo->prepare("SELECT s.id,s.role_code,s.created_at,s.last_seen_at,s.expires_at,s.revoked_at,u.full_name FROM security_sessions s JOIN system_users u ON u.id=s.user_id WHERE s.organization_id=? ORDER BY s.id DESC LIMIT 30");$s->execute([$orgId]);$sessions=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
