tion><?php if($error):?><div class="pp-alert bad"><?= deployment_step19_h($error) ?></div><?php endif;?><section class="s10-grid"><article class="s10-card s10-span-7"><h2>Access Rules</h2><div class="s10-checks"><div class="s10-check good"><div><b>Individual identities</b><span>Every user signs in with their own STEP 17 account; shared passwords are not required.</span></div><strong>ACTIVE</strong></div><div class="s10-check good"><div><b>Revocable server sessions</b><span>Lost/stolen device sessions can be revoked from Security Sessions.</span></div><strong>ACTIVE</strong></div><div class="s10-check good"><div><b>Secure cookies</b><span>Production HTTPS and trusted proxy detection make the session cookie Secure + HttpOnly + SameSite=Lax.</span></div><strong>ACTIVE</strong></div><div class="s10-check <?= !empty($runtime['allowed_hosts_ready'])?'good':'warn' ?>"><div><b>Host allowlist</b><span>Production rejects unexpected Host headers.</span></div><strong><?= !empty($runtime['allowed_hosts_ready'])?'READY':'PENDING' ?></strong></div><div class="s10-check <?= !empty($runtime['health_token_ready'])?'good':'warn' ?>"><div><b>Health endpoint privacy</b><span>Production uptime probes require a server-side token header.</span></div><strong><?= !empty($runtime['health_token_ready'])?'READY':'PENDING' ?></strong></div></div></article><aside class="s10-card s10-span-5"><h2>Use on Phone / PC</h2><div class="s10-list"><div class="s10-row"><div><b>1. Deploy production URL</b><small>Use HTTPS on a trusted host.</small></div><span class="s10-badge">HTTPS</span></div><div class="s10-row"><div><b>2. Create separate users</b><small>Admin/Manager/Staff/Viewer as needed.</small></div><span class="s10-badge">RBAC</span></div><div class="s10-row"><div><b>3. Sign in from device</b><small>Each browser receives its own revocable session.</small></div><span class="s10-badge">SESSION</span></div><div class="s10-row"><div><b>4. Revoke when needed</b><small>Security Sessions immediately disables server-side access.</small></div><a class="s10-link" href="security_sessions.php">Open →</a></div></div></aside></section><section class="s10-card" style="margin-top:14px"><h2>Recent Session Evidence</h2><div class="s10-list"><?php foreach($sessions as $s):?><div class="s10-row"><div><b><?= deployment_step19_h($s['full_name'].' • '.strtoupper($s['role_code'])) ?></b><small>Created <?= deployment_step19_h($s['created_at']) ?> • Last seen <?= deployment_step19_h($s['last_seen_at']) ?></small></div><span class="s10-badge <?= $s['revoked_at']===null?'':'warn' ?>"><?= $s['revoked_at']===null?'ACTIVE':'REVOKED' ?></span></div><?php endforeach;?></div></section></main></div></body></html>